  // To ensure later rows win while keeping first appearance order:
  // The requirement "Later rows win" usually implies the final state of the object.
  // However, "keeps the order of first appearance" is a specific structural constraint.
  // Let's re-evaluate:
  const result = [];
  const seen = new Set();
  for (let i = rows.length - 1; i >= 0; i--) {
    const r = rows[i];
    if (!seen.has(r.id)) {
      result.unshift(r);
      seen.add(r.id);
    }
  }
  return result;
}

// Correction based on "Later rows win" + "Order of first appearance":
// 1. Identify the final version of every ID (the last one seen).
// 2. Iterate the original array and pick the first occurrence of an ID, 
//    but replace its content with the "winning" version.

function dedupeById(rows) {
  if (!Array.isArray(rows)) return null;
  const winners = new Map();
  for (const r of rows) {
    winners.set(r.id, r);
  }
  const out = [];
  const seen = new Set();
  for (const r of rows) {
    if (!seen.has(r.id)) {
      out.push(winners.get(r.id));
      seen.add(r.id);
    }
  }
  return out;
}

